import NextAuth from "next-auth";
{{PROVIDER_IMPORTS}}
import { adapter } from "./infra/auth/adapter";

export const { handlers, auth, signIn, signOut } = NextAuth({
  adapter,
  providers: [
{{PROVIDER_ARRAY}}
  ],
  callbacks: {
    // Works for both database sessions (user provided) and JWT sessions
    // (token provided). With Credentials provider you'll see the JWT path.
    session({ session, token, user }) {
      if (session.user) {
        if (user?.id) session.user.id = user.id;
        else if (token?.sub) session.user.id = token.sub;
      }
      return session;
    },
  },
});

